-- EgyBook Reels: complete comments foundation (Neon + R2).
-- Additive and safe for empty/demo data. Does not touch Supabase.
BEGIN;

-- Ensure legacy bigint identifiers can be generated by INSERT statements.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['reels','reel_comments','reel_likes','reel_comment_notifications','reel_comment_reactions'] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema='public' AND table_name=t AND column_name='id'
          AND is_identity='YES'
      ) THEN
        EXECUTE format('ALTER TABLE public.%I ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY', t);
      END IF;
    END IF;
  END LOOP;
END $$;

ALTER TABLE public.reel_comments
  ADD COLUMN IF NOT EXISTS parent_comment_id bigint NULL,
  ADD COLUMN IF NOT EXISTS edited_at timestamptz NULL,
  ADD COLUMN IF NOT EXISTS is_pinned boolean NOT NULL DEFAULT false;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='reel_comments_parent_fk') THEN
    ALTER TABLE public.reel_comments ADD CONSTRAINT reel_comments_parent_fk
      FOREIGN KEY (parent_comment_id) REFERENCES public.reel_comments(id) ON DELETE CASCADE;
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.reel_comment_attachments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  comment_id bigint NOT NULL REFERENCES public.reel_comments(id) ON DELETE CASCADE,
  reel_id bigint NOT NULL REFERENCES public.reels(id) ON DELETE CASCADE,
  user_id text NOT NULL,
  attachment_type text NOT NULL CHECK (attachment_type IN ('image','audio','file')),
  object_key text NOT NULL,
  public_url text NOT NULL,
  mime_type text NOT NULL,
  file_name text NULL,
  file_size bigint NOT NULL DEFAULT 0 CHECK (file_size >= 0),
  duration_seconds numeric(8,2) NULL CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
  width integer NULL,
  height integer NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.reel_comment_mentions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  comment_id bigint NOT NULL REFERENCES public.reel_comments(id) ON DELETE CASCADE,
  mentioned_user_id text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(comment_id, mentioned_user_id)
);

CREATE TABLE IF NOT EXISTS public.reel_comment_reports (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  comment_id bigint NOT NULL REFERENCES public.reel_comments(id) ON DELETE CASCADE,
  reel_id bigint NOT NULL REFERENCES public.reels(id) ON DELETE CASCADE,
  reporter_user_id text NOT NULL,
  reason text NOT NULL,
  details text NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','reviewed','dismissed','actioned')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(comment_id, reporter_user_id)
);

CREATE TABLE IF NOT EXISTS public.reel_comment_hidden (
  comment_id bigint NOT NULL REFERENCES public.reel_comments(id) ON DELETE CASCADE,
  user_id text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(comment_id, user_id)
);

CREATE TABLE IF NOT EXISTS public.reel_comment_reactions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  comment_id bigint NOT NULL REFERENCES public.reel_comments(id) ON DELETE CASCADE,
  user_id text NOT NULL,
  reaction text NOT NULL CHECK (reaction IN ('👍','👎','❤️','😍','😮','😂','😢','😡')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reel_comment_reactions_comment_user_key UNIQUE(comment_id,user_id)
);

CREATE TABLE IF NOT EXISTS public.reel_comment_notifications (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  recipient_user_id text NOT NULL,
  actor_user_id text NOT NULL,
  reel_id bigint NOT NULL REFERENCES public.reels(id) ON DELETE CASCADE,
  comment_id bigint NOT NULL REFERENCES public.reel_comments(id) ON DELETE CASCADE,
  notification_type text NOT NULL CHECK (notification_type IN ('reply','reaction','mention')),
  reaction text NULL,
  is_read boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS reel_likes_reel_user_uidx ON public.reel_likes(reel_id,user_id);
CREATE INDEX IF NOT EXISTS idx_reel_comments_reel_created ON public.reel_comments(reel_id,created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS idx_reel_comments_parent ON public.reel_comments(parent_comment_id,created_at ASC,id ASC) WHERE parent_comment_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_reel_comment_attachments_comment ON public.reel_comment_attachments(comment_id,created_at);
CREATE INDEX IF NOT EXISTS idx_reel_comment_mentions_user ON public.reel_comment_mentions(mentioned_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reel_comment_notifications_recipient ON public.reel_comment_notifications(recipient_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reel_comment_reports_status ON public.reel_comment_reports(status,created_at DESC);

COMMIT;
